  function drillPool(kind,lv){
    const out=[];
    if(kind!=="verb"){
      NOUNS.filter(n=>n.lv<=lv).forEach(n=>n.f.forEach((f,i)=>{if(i%6===1&&lv<2)return;out.push({p:`<b>${E(n.h)}</b>`,q:`${CASES[i%6]} ${i<6?"singulier":"pluriel"}`,a:f,src:n.d})}));
      ADJS.filter(a=>a.lv<=lv).forEach(a=>CASES.forEach((c,ci)=>a.cols.forEach((col,k)=>{if(ci===1&&lv<2)return;out.push({p:`<b>${E(a.h)}</b>`,q:`${c} singulier · ${col}`,a:a.sg[ci][k],src:"Adjectif · "+a.d});out.push({p:`<b>${E(a.h)}</b>`,q:`${c} pluriel · ${col}`,a:a.pl[ci][k],src:"Adjectif · "+a.d})})));
      if(lv>=2)PRONS.forEach(p=>PCASES.forEach((c,ci)=>p.cols.forEach((col,k)=>{out.push({p:`<b>${E(p.h)}</b>`,q:`${c} singulier · ${col}`,a:p.sg[ci][k],src:"Pronom"});out.push({p:`<b>${E(p.h)}</b>`,q:`${c} pluriel · ${col}`,a:p.pl[ci][k],src:"Pronom"})})));
    }
    if(kind!=="noun"){
      VERBS.filter(v=>v.lv<=lv).forEach(v=>v.g.forEach(gr=>Object.entries(gr.t).forEach(([tn,forms])=>{
        if(lv<2&&(!BASIC_T.includes(tn)||!/Indicatif( actif)?$/.test(gr.m)))return;
        if(lv<3&&/Subjonctif passif|Plus-que-parfait|Futur antérieur/.test(gr.m+" "+tn))return;
        forms.forEach((f,i)=>{
          if(Array.isArray(f)){if(/Remarque|Participe parfait|Participe futur|Infinitif futur/.test(f[0]))return;out.push({p:`<b>${E(v.h)}</b>`,q:`${E(gr.m)} · ${f[0]}`,a:f[1],src:v.d})}
          else out.push({p:`<b>${E(v.h)}</b>`,q:`${E(gr.m)} · ${tn} · ${PERS[i]}`,a:f,src:v.d});
        });
      })));
    }
    return out;
  }
