  const RL_ALL=[["fr","🇫🇷 français"],["it","🇮🇹 italien"],["es","🇪🇸 espagnol"],["pt","🇵🇹 portugais"],["en","🇬🇧 anglais"],["de","🇩🇪 allemand"],["nl","🇳🇱 néerlandais"]];
