    if(g&&g.done)html+=`<div class="lw-card"><h3 style="margin:0">Résultat : ${g.score} / ${g.n}</h3><p class="lw-muted">+${g.score} XP</p></div>`;
    html+=`<div class="lw-card"><h3 style="margin:0 0 6px">Les racines latines</h3><p class="lw-muted">Le latin vit dans le français, l'italien, l'espagnol, le portugais… et dans une grande partie de l'anglais. Connaître la racine, c'est reconnaître des dizaines de mots d'un coup.</p><button class="lw-btn" style="margin-top:10px;width:100%" data-lw="rstart">Jouer : retrouve les familles (10 questions)</button></div>
    <input type="text" data-lw="rq" placeholder="Chercher un mot (latin, français, anglais…)" value="${E(st.rq||"")}" autocomplete="off">`;
    const q=plain(st.rq||"");
