  function rootCard(r){return `<div style="display:flex;align-items:baseline;gap:8px;flex-wrap:wrap"><span class="lw-big">${E(r.la)}</span><span class="lw-muted">${E(r.s)}</span><button class="lw-x" style="width:28px;height:28px;font-size:.8rem" data-lw="say" data-t="${E(r.la.split(/[ ,/]/)[0])}">🔊</button></div>
    <table class="lw-tbl" style="margin-top:6px">${rlist().map(([k,n])=>`<tr><th style="width:38%">${n}</th><td class="f"><span data-noi18n="1" lang="${k}">${E(k==="fr"?r.fr:r[k])}</span>${k==="fr"&&r.frs?`<span class="lw-muted" style="font-weight:600"> · mots savants : <span data-noi18n="1" lang="fr">${E(r.frs)}</span></span>`:""}</td></tr>`).join("")}</table>${r.n?`<p class="lw-muted" style="margin-top:8px">💡 ${E(r.n)}</p>`:""}`}
  function rootsStart(){const pick=shuffle(ROOTS).slice(0,10);st.rg={n:pick.length,i:0,score:0,ans:null,list:pick.map((r,i)=>mkRootQ(r,i%2?"down":"up"))};st.rg.cur=st.rg.list[0]}
  function mkRootQ(r,type){
    const clean=s=>s.replace(/[()]/g,"").split(",")[0].trim();
    let right,pool;
    if(type==="up"){right=r.la;pool=ROOTS.filter(x=>x!==r).map(x=>x.la)}
    else{const k=srcK(),w=x=>x[k]||x.fr;if(/^\(/.test(w(r)))type="up";right=type==="up"?r.la:clean(w(r));pool=ROOTS.filter(x=>x!==r&&!/^\(/.test(w(x))).map(x=>type==="up"?x.la:clean(w(x)))}
    const opts=shuffle([right,...shuffle(pool.filter(x=>x!==right)).slice(0,3)]);
    return {r,type,opts,ok:opts.indexOf(right)};
  }
  function versesV(){
    const vi=st.vi||0,v=VERSES[vi],ans=st.vans||(st.vans=v.s.map(()=>""));
    const checked=st.vchk;
    const mark=x=>x==="L"?"—":x==="S"?"∪":"?";
    let syl="",p=0;v.ft.forEach((n,fi)=>{const br=fi===v.brk;if(br)syl+=`<div style="flex-basis:100%;height:8px"></div>`;syl+=`<span style="display:inline-flex;gap:2px;padding:0 4px;${fi&&!br?"border-left:2px solid var(--line,#ccc)":""}">`;for(let j=0;j<n;j++,p++){const want=v.q[p],last=v.anc.has(p);const ok=checked&&(last?ans[p]!=="":ans[p]===want);
      syl+=`<button class="lw-opt" data-lw="vsyl" data-k="${p}" style="flex:0 0 auto;min-width:44px;padding:6px 6px;text-align:center;${checked?(ok?"border-color:var(--good,#2a2);background:var(--good-soft,#dfd)":"border-color:var(--bad,#c33);background:var(--bad-soft,#fdd)"):""}"><span style="display:block;font-size:1.05rem">${mark(checked&&!ok?want:ans[p])}</span><span style="font-weight:700">${E(v.s[p])}</span></button>`}syl+="</span>"});
    const feet=v.ft.map((n,fi)=>{const s=v.q.slice(v.ft.slice(0,fi).reduce((a,b)=>a+b,0),v.ft.slice(0,fi).reduce((a,b)=>a+b,0)+n);return (fi===v.brk?"‖ ":"")+(n===3?"dactyle":n===2?"spondée":"demi-pied (longue)")});
    const nOk=checked?v.s.filter((_,p)=>v.anc.has(p)?ans[p]!=="":ans[p]===v.q[p]).length:0;
    return `<div class="lw-card"><h3 style="margin:0 0 6px">Scander un vers latin</h3><p class="lw-muted">Touche chaque syllabe pour indiquer si elle est longue (—) ou brève (∪). Les barres séparent les pieds. La dernière syllabe d'un vers peut être longue ou brève (syllabe « indifférente »). ${VERSES.length} vers : hexamètres et un distique élégiaque.</p>
      <select data-lw="vsel" style="margin-top:8px">${VERSES.map((x,i)=>`<option value="${i}" ${i===vi?"selected":""}>${E(x.src)}</option>`).join("")}</select></div><p class="lw-tag" style="margin:0 2px">${v.m==="distique"?"Distique élégiaque : hexamètre + pentamètre":"Hexamètre dactylique"}${st.vhint?` · ${st.vhint} indice${st.vhint>1?"s":""} utilisé${st.vhint>1?"s":""}`:""}</p>
    <div class="lw-card"><div style="display:flex;flex-wrap:wrap;gap:6px 0;align-items:flex-start">${syl}</div><p class="lw-muted" style="margin-top:10px">${E(v.tr)}</p>
      <div class="lw-row" style="margin-top:10px"><button class="lw-btn" data-lw="vcheck" style="flex:1">Vérifier</button><button class="lw-btn alt" data-lw="vhint" style="flex:1">💡 Indice</button><button class="lw-btn alt" data-lw="vplay" style="flex:1">🥁 Rythme</button><button class="lw-btn alt" data-lw="say" data-t="${E(v.s.join(" ").replace(/ ’/g,"’"))}" style="flex:1">🔊 Lire</button></div></div>
    ${checked?`<div class="lw-fb ${nOk===v.s.length?"ok":"ko"}">${nOk===v.s.length?"Parfait ! Scansion exacte.":`${nOk} / ${v.s.length} syllabes justes. Les corrections sont affichées en rouge.`}</div>
      <div class="lw-card"><b>Les pieds :</b> ${feet.join(" · ")}<p class="lw-muted" style="margin-top:6px">${E(v.why)}</p><button class="lw-btn alt" data-lw="vnext" style="margin-top:10px;width:100%">Vers suivant →</button></div>`:""}
    <div class="lw-card"><b>Les règles à connaître</b><p class="lw-muted" style="margin-top:6px">• Longue par nature : voyelle longue (ā, ē, ī, ō, ū) ou diphtongue (ae, au, oe).<br>• Longue par position : voyelle suivie de deux consonnes, même dans le mot suivant (x et z comptent pour deux).<br>• Exception : une muette (b, p, d, t, g, c) suivie de l ou r peut laisser la syllabe brève.<br>• Élision : une voyelle finale (ou -m final) disparaît devant une voyelle ou un h.<br>• Hexamètre : six pieds ; dactyle — ∪ ∪ ou spondée — — ; le 5e pied est presque toujours un dactyle, le 6e a deux syllabes.<br>• Pentamètre : deux pieds (dactyles ou spondées), une longue, la coupe, puis deux dactyles et une dernière syllabe. Avec un hexamètre, il forme le distique élégiaque d'Ovide, Catulle, Tibulle et Properce.</p></div>`;
  }
  let actx=null;
  function playRhythm(v){try{actx=actx||new (window.AudioContext||window.webkitAudioContext)();let t=actx.currentTime+.05;let p=0;
    v.ft.forEach((n,fi)=>{if(fi===v.brk)t+=.5;for(let j=0;j<n;j++,p++){const L=v.q[p]==="L",dur=L?.36:.18;const o=actx.createOscillator(),g=actx.createGain();o.type="triangle";o.frequency.value=j===0?660:440;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(j===0?.35:.2,t+.01);g.gain.exponentialRampToValueAtTime(.001,t+dur*.9);o.connect(g);g.connect(actx.destination);o.start(t);o.stop(t+dur);t+=dur+.04}t+=.08})}catch(e){}}

