  function romeV(){
    const p=P(),R=rankOf(p.g);
    if(st.quest){
      const qs=QUESTS.find(x=>x.id===st.quest.id),q=st.quest,step=qs.steps[q.i];
      const ans=q.ans;let html=`<button class="lw-btn alt" data-lw="qback" style="align-self:flex-start">← Quitter la quête</button><div class="lw-stat"><span>${qs.e} ${E(qs.n)}</span><span>Étape ${q.i+1} / ${qs.steps.length}</span><span>⭐ ${q.score}</span></div>`;
      if(q.done){return html+`<div class="lw-card"><h3 style="margin:0 0 6px">Quête achevée !</h3><p class="lw-muted">${q.score} / ${qs.steps.length} bonnes réponses · +${q.score*2} gloria</p></div><button class="lw-btn" data-lw="qback">Retour à Rome</button>`}
      html+=`<div class="lw-card"><p style="margin:0;font-size:1.05rem;line-height:1.5">${E(step[0])}</p></div><div class="lw-card"><b>${E(step[1])}</b><div class="lw-row" style="margin-top:8px">${q.order.map(k=>`<button class="lw-opt ${ans!=null?(k===2?"ok":ans===k?"ko":""):""}" style="flex:1 1 100%" data-lw="qans" data-k="${k}" ${ans!=null?"disabled":""}>${E(step[k])}</button>`).join("")}</div></div>`;
      if(ans!=null)html+=`<div class="lw-fb ${ans===2?"ok":"ko"}">${ans===2?"Bene !":"Non."} <span style="font-weight:600">${E(step[5])}</span></div><button class="lw-btn" data-lw="qnext2">Continuer</button>`;
      return html;
    }
    const pct=R.next?Math.round((p.g-R.r.g)/(R.next.g-R.r.g)*100):100;
    const dq=dailyQ(),done=p.daily.last===dayIndex();
    let html=`<div class="lw-card" style="display:flex;gap:14px;align-items:center"><div style="font-size:2.6rem">${R.r.e}</div><div style="flex:1"><span class="lw-tag">Ton rang</span><div class="lw-big">${R.r.n}</div><p class="lw-muted">${E(R.r.d)} · ${p.g} gloria</p>
      <div style="height:10px;border-radius:99px;background:var(--surface-2,#eee);margin-top:8px;overflow:hidden"><div style="height:100%;width:${pct}%;background:var(--gold,#e6b800)"></div></div><p class="lw-muted" style="margin-top:4px;font-size:.8rem">${R.next?`Encore ${R.next.g-p.g} gloria pour devenir ${R.next.n}`:"Rang suprême atteint : Ave, Imperator !"}</p></div></div>`;
    html+=`<div class="lw-card"><span class="lw-tag">📅 Citation du jour${p.daily.streak>1?` · série de ${p.daily.streak} jours`:""}</span><div class="lw-big" style="margin:6px 0">${E(dq.q.la)} <button class="lw-x" style="width:30px;height:30px;font-size:.8rem" data-lw="say" data-t="${E(dq.q.la)}">🔊</button></div>
      ${done?`${p.daily.ok?`<div class="lw-fb ok" style="margin-bottom:6px">Bene ! +3 gloria</div>`:`<div class="lw-fb ko" style="margin-bottom:6px">Pas cette fois : voici la bonne traduction.</div>`}<p style="margin:0"><b>${E(dq.q.fr)}</b></p><p class="lw-muted">${E(dq.q.src)} · reviens demain pour une nouvelle citation !</p>`:`<b>Que signifie-t-elle ?</b><div class="lw-row" style="margin-top:8px">${dq.opts.map((o,k)=>`<button class="lw-opt" style="flex:1 1 100%" data-lw="dq" data-k="${k}">${E(o)}</button>`).join("")}</div>`}</div>`;
    html+=`<h3 style="margin:6px 2px 0">Quêtes</h3>`+QUESTS.map(q=>`<button class="lw-entry" data-lw="qopen" data-k="${q.id}"><span class="lw-ico">${q.e}</span><span style="flex:1"><b>${E(q.n)} ${p.quests[q.id]?"✅":""}</b><small>${E(q.d)} · niveau ${q.lv}</small></span></button>`).join("");
    html+=`<h3 style="margin:6px 2px 0">Insignes (${Object.keys(p.b).length} / ${BADGES.length})</h3><div class="lw-grid">${BADGES.map(b=>`<div class="lw-card" style="${p.b[b.id]?"":"opacity:.45;filter:grayscale(1)"}"><div style="font-size:1.6rem">${b.e}</div><b>${E(b.n)}</b><p class="lw-muted">${E(b.d)}</p></div>`).join("")}</div>`;
    html+=`<h3 style="margin:6px 2px 0">Le cursus honorum</h3><div class="lw-card"><table class="lw-tbl">${RANKS.map((r,i)=>`<tr style="${i===R.i?"background:var(--gold-soft,#ffefb0)":""}"><th>${r.e} ${r.g}</th><td class="f">${r.n}</td><td class="lw-muted">${E(r.d)}</td></tr>`).join("")}</table><p class="lw-muted" style="margin-top:8px">Chaque bonne réponse dans l'atelier rapporte de la gloria : formes, cas, textes, racines, vers, quêtes et citation du jour.</p></div>`;
    return html;
  }

